{"path": "E:\AgentSuper\backend\tetris\style.css", "content": ":root {
  --bg: #0f1226;
  --bg-2: #171a35;
  --panel: rgba(255, 255, 255, 0.05);
  --border: rgba(255, 255, 255, 0.12);
  --text: #e8ecff;
  --muted: #9aa3c7;
  --accent: #5b8cff;
  --accent-2: #22d3a6;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  color: var(--text);
  background:
    radial-gradient(1200px 600px at 15% -10%, #26306b 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #1d4d55 0%, transparent 55%),
    linear-gradient(160deg, var(--bg) 0%, var(--bg-2) 100%);
  background-attachment: fixed;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.game-wrap {
  width: 100%;
  max-width: 720px;
}

.title {
  text-align: center;
  margin-bottom: 18px;
}

.title h1 {
  margin: 0;
  font-size: clamp(24px, 5vw, 36px);
  letter-spacing: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--muted);
}

.stage {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  justify-content: center;
  flex-wrap: wrap;
}

/* ---------- 主棋盘 ---------- */
.board-panel {
  position: relative;
  border-radius: 16px;
  padding: 10px;
  background: var(--panel);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  backdrop-filter: blur(6px);
}

#board {
  display: block;
  border-radius: 10px;
  background: #0a0d1f;
  touch-action: none;
}

/* ---------- 侧栏 ---------- */
.side {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 190px;
}

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 12px 14px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(6px);
}

.card h3 {
  margin: 0 0 10px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--muted);
  text-transform: uppercase;
}

#next {
  display: block;
  margin: 0 auto;
  border-radius: 8px;
  background: #0a0d1f;
}

.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat .label {
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 1px;
}

.stat .value {
  font-size: 20px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent-2);
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.btn {
  appearance: none;
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.06);
  color: var(--text);
  font-size: 14px;
  padding: 10px 12px;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.08s ease, background 0.2s ease, border-color 0.2s ease;
}

.btn:hover { background: rgba(255, 255, 255, 0.12); border-color: var(--accent); }
.btn:active { transform: scale(0.97); }

.btn.primary {
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  border: none;
  color: #06122b;
  font-weight: 700;
}

.help ul {
  margin: 0;
  padding-left: 0;
  list-style: none;
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.9;
}

kbd {
  display: inline-block;
  min-width: 20px;
  padding: 1px 6px;
  font-family: inherit;
  font-size: 11px;
  text-align: center;
  color: var(--text);
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 5px;
}

/* ---------- 遮罩层 ---------- */
.overlay {
  position: absolute;
  inset: 10px;
  border-radius: 10px;
  background: rgba(6, 9, 24, 0.82);
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(3px);
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-card {
  text-align: center;
  padding: 20px;
}

.overlay-card h2 {
  margin: 0 0 8px;
  font-size: 24px;
  letter-spacing: 2px;
}

.overlay-card p {
  margin: 0 0 16px;
  font-size: 13px;
  color: var(--muted);
}

@media (max-width: 560px) {
  .stage { flex-direction: column; align-items: center; }
  .side { width: 100%; max-width: 320px; }
  .stats { grid-template-columns: 1fr 1fr; }
}
"}
